sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === oldValue) {
        return;
    }

    var trainingSysId = g_form.getValue('training');
    var date = g_form.getValue('date');
    var dateParts = date.split('/'); 
    var formattedDate = dateParts[2] + '-' + dateParts[1] + '-' + dateParts[0]; 

    var gaSchedule = new GlideAjax('x_1593191_cooknow.DateDuplicate');
    gaSchedule.addParam('sysparm_name', 'checkDuplicates');
    gaSchedule.addParam('sysparm_trainingSysId', trainingSysId);
    gaSchedule.addParam('sysparm_date', formattedDate); 

    gaSchedule.getXMLAnswer(function(response) {
        if (response === 'true') {
            g_form.addErrorMessage("We cannot have the same training in the same day. Please, select another date.");
            g_form.setValue('date', "");  
        } else {
			g_form.clearMessages();
		}
    });
}
